The following Verilog code implements an AXI4-Lite clock-domain bridge:

```
module axil_cdc #
(
    parameter DATA_WIDTH = 32,
    parameter ADDR_WIDTH = 32,
    parameter STRB_WIDTH = (DATA_WIDTH/8)
)
(
    /*
     * AXI lite slave interface
     */
    input  wire                   s_clk,
    input  wire                   s_rst,
    input  wire [ADDR_WIDTH-1:0]  s_axil_awaddr,
    input  wire [2:0]             s_axil_awprot,
    input  wire                   s_axil_awvalid,
    output wire                   s_axil_awready,
    input  wire [DATA_WIDTH-1:0]  s_axil_wdata,
    input  wire [STRB_WIDTH-1:0]  s_axil_wstrb,
    input  wire                   s_axil_wvalid,
    output wire                   s_axil_wready,
    output wire [1:0]             s_axil_bresp,
    output wire                   s_axil_bvalid,
    input  wire                   s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]  s_axil_araddr,
    input  wire [2:0]             s_axil_arprot,
    input  wire                   s_axil_arvalid,
    output wire                   s_axil_arready,
    output wire [DATA_WIDTH-1:0]  s_axil_rdata,
    output wire [1:0]             s_axil_rresp,
    output wire                   s_axil_rvalid,
    input  wire                   s_axil_rready,
    /*
     * AXI lite master interface
     */
    input  wire                   m_clk,
    input  wire                   m_rst,
    output wire [ADDR_WIDTH-1:0]  m_axil_awaddr,
    output wire [2:0]             m_axil_awprot,
    output wire                   m_axil_awvalid,
    input  wire                   m_axil_awready,
    output wire [DATA_WIDTH-1:0]  m_axil_wdata,
    output wire [STRB_WIDTH-1:0]  m_axil_wstrb,
    output wire                   m_axil_wvalid,
    input  wire                   m_axil_wready,
    input  wire [1:0]             m_axil_bresp,
    input  wire                   m_axil_bvalid,
    output wire                   m_axil_bready,
    output wire [ADDR_WIDTH-1:0]  m_axil_araddr,
    output wire [2:0]             m_axil_arprot,
    output wire                   m_axil_arvalid,
    input  wire                   m_axil_arready,
    input  wire [DATA_WIDTH-1:0]  m_axil_rdata,
    input  wire [1:0]             m_axil_rresp,
    input  wire                   m_axil_rvalid,
    output wire                   m_axil_rready
);

    // Internal signals
    reg [DATA_WIDTH-1:0] s_axil_wdata_reg;
    reg [STRB_WIDTH-1:0] s_axil_wstrb_reg;
    reg [ADDR_WIDTH-1:0] s_axil_awaddr_reg;
    reg [2:0] s_axil_awprot_reg;
    reg s_axil_awvalid_reg;
    reg s_axil_wvalid_reg;
    reg s_axil_arvalid_reg;
    reg [ADDR_WIDTH-1:0] s_axil_araddr_reg;
    reg [2:0] s_axil_arprot_reg;
    reg [DATA_WIDTH-1:0] m_axil_rdata_reg;
    reg [1:0] m_axil_rresp_reg;
    reg m_axil_rvalid_reg;
    reg [ADDR_WIDTH-1:0] m_axil_awaddr_reg;
    reg [2:0] m_axil_awprot_reg;
    reg m_axil_awvalid_reg;
    reg [DATA_WIDTH-1:0] m_axil_wdata_reg;
    reg [STRB_WIDTH-1:0] m_axil_wstrb_reg;
    reg m_axil_wvalid_reg;
    reg [ADDR_WIDTH-1:0] m_axil_araddr_reg;
    reg [2:0] m_axil_arprot_reg;
    reg m_axil_arvalid_reg;
    reg m_axil_bready_reg;
    reg m_axil_rready_reg;

    // State machine signals
    reg [1:0] state;
    localparam IDLE = 2'b00;
    localparam WRITE = 2'b01;
    localparam READ = 2'b10;

    // State machine
    always @(posedge s_clk) begin
        if (s_rst) begin
            state <= IDLE;
            s_axil_awready <= 1'b0;
            s_axil_wready <= 1'b0;
            s_axil_bresp <= 2'b00;
            s_axil_bvalid <= 1'b0;
            s_axil_arready <= 1'b0;
            s_axil_rdata <= 32'h0;
            s_axil_rresp <= 2'b00;
            s_axil_rvalid <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (s_axil_awvalid) begin
                        s_axil_awready <= 1'b1;
                        s_axil_awaddr_reg <= s_axil_awaddr;
                        s_axil_awprot_reg <= s_axil_awprot;
                        s_axil_awvalid_reg <= 1'b1;
                        state <= WRITE;
                    end else if (s_axil_arvalid) begin
                        s_axil_arready <= 1'b1;
                        s_axil_araddr_reg <= s_axil_araddr;
                        s_axil_arprot_reg <= s_axil_arprot;
                        s_axil_arvalid_reg <= 1'b1;
                        state <= READ;
                    end
                end
                WRITE: begin
                    if (s_axil_wvalid) begin
                        s_axil_wready <= 1'b1;
                        s_axil_wdata_reg <= s_axil_wdata;
                        s_axil_wstrb_reg <= s_axil_wstrb;
                        s_axil_wvalid_reg <= 1'b1;
                        state <= IDLE;
                    end
                end
                READ: begin
                    if (m_axil_rvalid) begin
                        s_axil_rdata <= m_axil_rdata_reg;
                        s_axil_rresp <= m_axil_rresp_reg;
                        s_axil_rvalid <= 1'b1;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

    // Master interface
    always @(posedge m_clk) begin
        if (m_rst) begin
            m_axil_awaddr_reg <= 32'h0;
            m_axil_awprot_reg <= 3'b000;
            m_axil_awvalid_reg <= 1'b0;
            m_axil_wdata_reg <= 32'h0;
            m_axil_wstrb_reg <= 4'b0000;
            m_axil_wvalid_reg <= 1'b0;
            m_axil_bready_reg <= 1'b0;
            m_axil_araddr_reg <= 32'h0;
            m_axil_arprot_reg <= 3'b000;
            m_axil_arvalid_reg <= 1'b0;
            m_axil_rready_reg <= 1'b0;
        end else begin
            if (m_axil_awready) begin
                m_axil_awaddr_reg <= s_axil_awaddr_reg;
                m_axil_awprot_reg <= s_axil_awprot_reg;
                m_axil_awvalid_reg <= s_axil_awvalid_reg;
            end
            if (m_axil_wready) begin
                m_axil_wdata_reg <= s_axil_wdata_reg;
                m_axil_wstrb_reg <= s_axil_wstrb_reg;
                m_axil_wvalid_reg <= s_axil_wvalid_reg;
            end
            if (m_axil_bvalid) begin
                m_axil_bresp <= m_axil_bresp_reg;
                m_axil_bvalid_reg <= s_axil_bvalid_reg;
                m_axil_bready_reg <= s_axil_bready;
            end
            if (m_axil_arready) begin
                m_axil_araddr_reg <= s_axil_araddr_reg;
                m_axil_arprot_reg <= s_axil_arprot_reg;
                m_axil_arvalid_reg <= s_axil_arvalid_reg;
            end
            if (m_axil_rvalid) begin
                m_axil_rdata_reg <= s_axil_rdata;
                m_axil_rresp_reg <= s_axil_rresp;
                m_axil_rvalid_reg <= s_axil_rvalid;
                m_axil_rready_reg <= s_axil_rready;
            end
        end
    end

    // Output assignments
    assign m_axil_awaddr = m_axil_awaddr_reg;
    assign m_axil_awprot = m_axil_awprot_reg;
    assign m_axil_awvalid = m_axil_awvalid_reg;
    assign m_axil_wdata = m_axil_wdata_reg;
    assign m_axil_wstrb = m_axil_wstrb_reg;
    assign m_axil_wvalid = m_axil_wvalid_reg;
    assign m_axil_bready = m_axil_bready_reg;
    assign m_axil_araddr = m_axil_araddr_reg;
    assign m_axil_arprot = m_axil_arprot_reg;
    assign m_axil_arvalid = m_axil_arvalid_reg;
    assign m_axil_rready = m_axil_rready_reg;

endmodule<｜end▁of▁sentence｜><｜begin▁of▁sentence｜>module top_module(
